INSERT INTO exam_portal_certificatetemplate VALUES(6,'CertificateTemplate/certificate_template_page-0001_YTmntkn_CYxsdrt.jpg','presented by principle','School Principal I, Teodoro Evangelista Memorial High School',replace(replace('for her active participation during the conduct of the Division Assessors’ Orientation on Expanded Career\r\n\r\n\r\n\r\n\r\n','\r',char(13)),'\n',char(10)),replace(replace('Progression System for Public School Teachers, held on May 15, 2025, at BALHCEI, Baliwag South Central School, City of Baliwag, Bulacan, per Division Memorandum No. 213 s. 2025.\r\n \r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n','\r',char(13)),'\n',char(10)),replace(replace('Given this 15th day of May 2025 at the BaliwagHenyo Center of Excellence and Innovation (BALHCEI), Baliwag South Central School, City of Baliwag, Bulacan.\r\n\r\n\r\n\r\n\r\n\r\n\r\n','\r',char(13)),'\n',char(10)),14,'John Philip Baylon','Certificate of Participation');
INSERT INTO webinar_webinar VALUES(14,'Digital Transformation in educational workshop','This refers to the integration of digital technologies into educational workshops to enhance teaching, learning, and administrative processes. It involves shifting from traditional methods to more interactive, data-driven, and tech-enabled approaches—such as using online platforms, digital tools, virtual classrooms, and AI-driven content. ',1,'workshop','2025-04-05','2025-04-05','banner/digital_transformation_in_education_workshop.png','Baliuag South Central School, J. Buizon St, Baliwag','10:00');
INSERT INTO webinar_webinar VALUES(15,'Educational Leadership & Innovation Summit','The Educational Leadership & Innovation Summit is a gathering of educators, administrators, and thought leaders aimed at exploring forward-thinking strategies to improve education. The summit focuses on leadership development, innovative teaching practices, and the integration of new technologies to drive meaningful change in schools and institutions. It serves as a platform for sharing ideas, best practices, and collaborative solutions to shape the future of education.',2,'seminar','2025-04-05','2025-04-05','banner/educational_leadership_and_innovation_summit.png','Baliuag South Central School, J. Buizon St, Baliwag','11:30');
INSERT INTO webinar_webinar VALUES(16,'math','description',1,'recognition','2025-04-07','2025-04-08','banner/digital_transformation_in_education_workshop_d8AK0KR.png','Baliuag South Central School, J. Buizon St, Baliwag','00:03');
INSERT INTO webinar_webinar VALUES(18,' Empowering Educators: Effective Strategies for Hybrid Classrooms',replace(replace('\r\nThis webinar explores practical approaches to managing hybrid learning environments. Participants will learn how to balance in-person and virtual instruction, integrate digital tools effectively, and foster student engagement across both formats.','\r',char(13)),'\n',char(10)),1,'recognition','2025-07-16','2025-07-16','banner/webinar_2.png','Bagon Nayon, Baliuag Bulacan','10:00:00');
INSERT INTO webinar_webinar VALUES(19,'Digital Tools for Modern Teaching',replace(replace('This webinar introduces essential digital platforms and applications that enhance classroom engagement, streamline assessment, and support differentiated instruction. Ideal for educators seeking to modernize their teaching practices.\r\n','\r',char(13)),'\n',char(10)),1,'recognition','2025-06-17','2025-06-17','banner/webinar_1.png',' Bagon Nayon, Baliuag Bulacan','15:00:00');
INSERT INTO webinar_webinar VALUES(20,'Building Inclusive and Collaborative Learning Environments','Explore techniques to foster inclusivity, cultural responsiveness, and collaboration in the classroom. Learn how to create safe, equitable spaces where every learner feels valued and engaged.',1,'recognition','2025-06-18','2025-06-18','banner/webinar_3.png',' Bagon Nayon, Baliuag Bulacan','13:00:00');
INSERT INTO webinar_webinar VALUES(21,'Future-Proofing Your Career with AI & Automation','Join us for a thought-provoking online session exploring how artificial intelligence and automation are reshaping industries. Discover the skills you need to remain competitive, and how to ethically and effectively integrate AI tools into your workflow. This webinar is ideal for professionals, students, and entrepreneurs eager to stay ahead in the tech-driven job market.',1,'seminar','2025-10-18','2025-10-18','banner/seminar_1.png','Bagong Nayon, Baliuag, Bulacan','07:00:00');
INSERT INTO webinar_webinar VALUES(22,'Leadership in the Digital Era: Building Influence and Impact','This in-person seminar will empower participants with the tools to lead with confidence in a rapidly evolving digital landscape. Learn effective communication, influence strategies, and digital decision-making techniques from an industry veteran. The session includes breakout discussions, real-world case studies, and networking.',1,'recognition','2025-10-16','2025-10-16','banner/seminar_2.png','Bagong Nayon, Baliuag, Bulacan','07:00:00');
INSERT INTO webinar_webinar VALUES(23,'Hands-On UI/UX Design: From Wireframes to Interactive Prototypes','Dive into the fundamentals of user interface and experience design in this practical workshop. Participants will learn to create intuitive layouts, prototype using Figma, and test user flows. Perfect for aspiring designers or developers looking to sharpen their design thinking.',1,'seminar','2025-10-17','2025-12-12','banner/seminar_3.png','Bagong Nayon, Baliuag, Bulacan','06:00:00');
