PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE IF NOT EXISTS "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "webinar_responsequestionaire" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "q1" integer NULL, "q2" integer NULL, "q3" integer NULL, "q4" integer NULL, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "webinar_id" bigint NOT NULL REFERENCES "webinar_webinar" ("id") DEFERRABLE INITIALLY DEFERRED, "q5" integer NULL, "q6" integer NULL, "type" varchar(100) NULL);
CREATE TABLE IF NOT EXISTS "webinar_test_question" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "question" varchar(500) NULL, "question_type" varchar(50) NULL, "webinar_id" bigint NULL REFERENCES "webinar_webinar" ("id") DEFERRABLE INITIALLY DEFERRED, "correct_answered" varchar(200) NULL, "test_type" varchar(30) NULL);
CREATE TABLE IF NOT EXISTS "webinar_choice" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "text_option" varchar(200) NULL, "question_id" bigint NULL REFERENCES "webinar_test_question" ("id") DEFERRABLE INITIALLY DEFERRED, "is_correct" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "webinar_testresponse" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "question_id" bigint NULL REFERENCES "webinar_test_question" ("id") DEFERRABLE INITIALLY DEFERRED, "user_input" varchar(200) NULL, "is_correct" bool NOT NULL, "user_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "exam_portal_testresult" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "test" varchar(50) NOT NULL, "score" integer NOT NULL, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "webinar_id" bigint NULL REFERENCES "webinar_webinar" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "exam_portal_certificatetemplate" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "img" varchar(100) NOT NULL, "subtitle" varchar(100) NULL, "host" varchar(100) NULL, "subject" text NULL, "address" text NULL, "date" text NULL, "webinar_id" bigint NOT NULL REFERENCES "webinar_webinar" ("id") DEFERRABLE INITIALLY DEFERRED, "participant" varchar(100) NULL, "title" varchar(100) NULL);
CREATE TABLE IF NOT EXISTS "webinar_webinar" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(20) NOT NULL, "description" varchar(1000) NOT NULL, "number_of_speaker" integer NOT NULL, "event_type" varchar(20) NULL, "start_date" date NULL, "until_date" date NULL, "banner" varchar(100) NOT NULL, "venue" varchar(40) NOT NULL, "time" time NOT NULL);
CREATE TABLE IF NOT EXISTS "login_userprofile" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "school_id" varchar(100) NULL, "number" varchar(100) NULL, "user_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "school" varchar(100) NULL, "img" varchar(100) NULL);
CREATE TABLE IF NOT EXISTS "webinar_speaker" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "webinar_id" bigint NOT NULL REFERENCES "webinar_webinar" ("id") DEFERRABLE INITIALLY DEFERRED, "name" varchar(30) NOT NULL, "email" varchar(30) NULL, "img" varchar(100) NULL);
CREATE TABLE IF NOT EXISTS "webinar_comment" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "text" text NOT NULL, "Webinar_id" bigint NOT NULL REFERENCES "webinar_webinar" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "exam_portal_testqr" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(50) NOT NULL, "img" varchar(100) NOT NULL, "type" varchar(40) NULL, "test_id" bigint NOT NULL REFERENCES "webinar_webinar" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "exam_portal_evalqr" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "type" varchar(40) NULL, "name" varchar(50) NOT NULL, "img" varchar(100) NOT NULL, "test_id" bigint NOT NULL REFERENCES "webinar_webinar" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "webinar_webinarattendees" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "school_id" varchar(20) NULL, "email" varchar(254) NOT NULL, "webinar_id" bigint NOT NULL REFERENCES "webinar_webinar" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "attendance" integer NOT NULL);
DELETE FROM sqlite_sequence;
